56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    public OwnerRestControllerV1(ClinicService clinicService,
70	                                 OwnerMapper ownerMapper,
71	                                 PetMapper petMapper,
72	                                 VisitMapper visitMapper) {
73	        this.clinicService = clinicService;
74	        this.ownerMapper = ownerMapper;
75	        this.petMapper = petMapper;
76	        this.visitMapper = visitMapper;
77	    }
78	
79	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
80	    @Override
81	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
82	        Collection<Owner> owners;
83	        if (lastName != null) {
84	            owners = this.clinicService.findOwnerByLastName(lastName);
85	        } else {
86	            owners = this.clinicService.findAllOwners();
87	        }
88	        if (owners.isEmpty()) {
89	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
90	        }
91	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
97	        Owner owner = this.clinicService.findOwnerById(ownerId);
98	        if (owner == null) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
107	        HttpHeaders headers = new HttpHeaders();
108	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
109	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
110	        owner.setTelephone(normalizedTelephone);
111	        owner.setEmail(normalizeEmail(owner.getEmail()));
112	        owner.setAddress(normalizeAddress(owner.getAddress()));
113	        if (owner.getRegistrationDate() == null) {
114	            owner.setRegistrationDate(LocalDate.now());
115	        }
116	        if (countOwnersRegisteredToday() >= DAILY_CREATE_LIMIT) {
117	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
118	                "the maximum number of owners that may be created today has been reached");
119	        }
120	        if (isTelephoneInUse(normalizedTelephone, null)) {
121	            throw new ResponseStatusException(HttpStatus.CONFLICT,
122	                "telephone is already in use by another owner");
123	        }
124	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
125	        if (!sharesHousehold
126	            && this.clinicService.isHouseholdInUse(owner.getLastName(), owner.getAddress(), null)) {
127	            throw new ResponseStatusException(HttpStatus.CONFLICT,
128	                "another owner with the same last name already lives at this address");
129	        }
130	        if (countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
131	            throw new ResponseStatusException(HttpStatus.CONFLICT,
132	                "city has reached its maximum number of owners");
133	        }
134	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
135	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
136	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
137	        if (sharesHousehold) {
138	            this.clinicService.assignHousehold(owner);
139	        }
140	        this.clinicService.saveOwner(owner);
141	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
142	        headers.setLocation(UriComponentsBuilder.newInstance()
143	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
144	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
145	    }
146	
147	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
148	    @Override
149	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
150	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
151	        if (currentOwner == null) {
152	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
153	        }
154	        currentOwner.setAddress(ownerFieldsDto.getAddress());
155	        currentOwner.setCity(ownerFieldsDto.getCity());
156	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
157	        currentOwner.setLastName(ownerFieldsDto.getLastName());
158	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
159	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
160	        this.clinicService.saveOwner(currentOwner);
161	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
162	    }
163	
164	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
165	    @Transactional
166	    @Override
167	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
168	        Owner owner = this.clinicService.findOwnerById(ownerId);
169	        if (owner == null) {
170	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
171	        }
172	        this.clinicService.deleteOwner(owner);
173	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Override
178	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
179	        Owner owner = this.clinicService.findOwnerById(ownerId);
180	        if (owner == null) {
181	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
182	        }
183	        HttpHeaders headers = new HttpHeaders();
184	        Pet pet = petMapper.toPet(petFieldsDto);
185	        owner.setId(ownerId);
186	        pet.setOwner(owner);
187	        pet.getType().setName(null);
188	        this.clinicService.savePet(pet);
189	        PetDto petDto = petMapper.toPetDto(pet);
190	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
191	            .buildAndExpand(pet.getId()).toUri());
192	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
193	    }
194	
195	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
196	    @Override
197	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
198	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
199	        if (currentOwner != null) {
200	            Pet currentPet = this.clinicService.findPetById(petId);
201	            if (currentPet != null) {
202	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
203	                currentPet.setName(petFieldsDto.getName());
204	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
205	                this.clinicService.savePet(currentPet);
206	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
207	            }
208	        }
209	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
210	    }
211	
212	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
213	    @Override
214	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
215	        HttpHeaders headers = new HttpHeaders();
216	        Visit visit = visitMapper.toVisit(visitFieldsDto);
217	        Pet pet = new Pet();
218	        pet.setId(petId);
219	        visit.setPet(pet);
220	        this.clinicService.saveVisit(visit);
221	        VisitDto visitDto = visitMapper.toVisitDto(visit);
222	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
223	            .buildAndExpand(visit.getId()).toUri());
224	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
225	    }
226	
227	
228	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
229	    @Override
230	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
231	        Owner owner = this.clinicService.findOwnerById(ownerId);
232	        if (owner != null) {
233	            Pet pet = owner.getPet(petId);
234	            if (pet != null) {
235	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
236	            }
237	        }
238	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
239	    }
240	
241	    /**
242	     * Builds the customer code for a new owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is
243	     * the upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
244	     * last name, and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
245	     * owners that already live in that city (e.g. {@code 'LON-SMI-0007'}).
246	     *
247	     * @param city     the owner's city
248	     * @param lastName the owner's last name
249	     * @return the assigned customer code
250	     */
251	    private String nextCustomerCode(String city, String lastName) {
252	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
253	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
254	        int sequence = countOwnersInCity(city) + 1;
255	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
256	    }
257	
258	    /**
259	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
260	     * owner's city already contains this many owners.
261	     */
262	    private static final int CITY_CAPACITY = 50;
263	
264	    /**
265	     * The maximum number of owners that may be created on a single day. A create is rejected with
266	     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
267	     * {@code registrationDate}.
268	     */
269	    private static final int DAILY_CREATE_LIMIT = 100;
270	
271	    /**
272	     * Counts the existing owners whose {@code registrationDate} is today, i.e. the number of owners
273	     * that have already been created today. Called before a new owner is saved, so the returned
274	     * value reflects the number of owners created earlier today prior to this create.
275	     *
276	     * @return the number of existing owners registered today
277	     */
278	    private int countOwnersRegisteredToday() {
279	        LocalDate today = LocalDate.now();
280	        return (int) this.clinicService.findAllOwners().stream()
281	            .filter(existing -> today.equals(existing.getRegistrationDate()))
282	            .count();
283	    }
284	
285	    /**
286	     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
287	     *
288	     * @param city the city to count owners for
289	     * @return the number of existing owners in that city
290	     */
291	    private int countOwnersInCity(String city) {
292	        return (int) this.clinicService.findAllOwners().stream()
293	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
294	            .count();
295	    }
296	
297	    /**
298	     * Builds the membership number for a new owner, formatted {@code '<customerCode>-M<YY>'} where YY is
299	     * the last two digits of the registration date's year (e.g. {@code 'LON-SMI-0007-M26'}).
300	     *
301	     * @param customerCode     the owner's assigned customer code
302	     * @param registrationDate the owner's registration date
303	     * @return the assigned membership number
304	     */
305	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
306	        String yy = String.format("%02d", registrationDate.getYear() % 100);
307	        return String.format("%s-M%s", customerCode, yy);
308	    }
309	
310	    /**
311	     * Counts the existing owners that already share the given first name and last name, comparing
312	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
313	     * the number of namesakes that existed prior to this create.
314	     *
315	     * @param firstName the new owner's first name
316	     * @param lastName  the new owner's last name
317	     * @return the number of existing owners with the same first and last name
318	     */
319	    private int countNamesakes(String firstName, String lastName) {
320	        int count = 0;
321	        for (Owner existing : this.clinicService.findAllOwners()) {
322	            if (firstName.equalsIgnoreCase(existing.getFirstName())
323	                && lastName.equalsIgnoreCase(existing.getLastName())) {
324	                count++;
325	            }
326	        }
327	        return count;
328	    }
329	
330	    /**
331	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
332	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
333	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
334	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
335	     * string is what gets stored and returned.
336	     *
337	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
338	     *
339	     * @param telephone the raw telephone value supplied by the client
340	     * @return the normalized E.164 telephone number
341	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
342	     *                                 valid E.164 number (unexpected characters, or not 8 to 15
343	     *                                 digits after the {@code '+'})
344	     */
345	    private static String normalizeTelephone(String telephone) {
346	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
347	        String digits;
348	        if (cleaned.startsWith("+")) {
349	            digits = cleaned.substring(1);
350	        } else {
351	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
352	            digits = "61" + national;
353	        }
354	        if (!digits.matches("[0-9]{8,15}")) {
355	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
356	                "telephone could not be normalized to a valid E.164 number");
357	        }
358	        return "+" + digits;
359	    }
360	
361	    /**
362	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, falling back
363	     * to the raw stored value if it cannot be normalized (e.g. legacy seed data in another format).
364	     *
365	     * @param telephone the stored telephone value, possibly {@code null}
366	     * @return the E.164 form, or the raw value when it cannot be normalized
367	     */
368	    private static String toComparableTelephone(String telephone) {
369	        try {
370	            return normalizeTelephone(telephone);
371	        } catch (ResponseStatusException ex) {
372	            return telephone;
373	        }
374	    }
375	
376	    /**
377	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
378	     * containing at least one dot, none of the three sections containing whitespace or an
379	     * additional {@code @}.
380	     */
381	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
382	
383	    /**
384	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
385	     * (email is optional). When a value is supplied it must be a syntactically valid address; the
386	     * value is then stored and returned lower-cased.
387	     *
388	     * @param email the raw email value supplied by the client, possibly {@code null}
389	     * @return the lower-cased email, or {@code null} when none was supplied
390	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
391	     *                                 is not a syntactically valid address
392	     */
393	    private static String normalizeEmail(String email) {
394	        if (email == null) {
395	            return null;
396	        }
397	        if (!EMAIL_PATTERN.matcher(email).matches()) {
398	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
399	                "email must be a syntactically valid address");
400	        }
401	        return email.toLowerCase(Locale.ROOT);
402	    }
403	
404	    /**
405	     * Common street-type abbreviations expanded to their full word during address normalization.
406	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
407	     */
408	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
409	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
410	
411	    /**
412	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
413	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
414	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
415	     * {@code AVE -> AVENUE}). This normalized value is what gets stored, returned, and used for every
416	     * address comparison (household duplicate detection and the shared household id).
417	     *
418	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
419	     *
420	     * @param address the raw address supplied by the client, possibly {@code null}
421	     * @return the normalized address
422	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
423	     *                                 after normalization (required field)
424	     */
425	    private static String normalizeAddress(String address) {
426	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
427	        if (collapsed.isEmpty()) {
428	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
429	                "address must not be blank");
430	        }
431	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
432	        StringBuilder normalized = new StringBuilder();
433	        for (int i = 0; i < tokens.length; i++) {
434	            if (i > 0) {
435	                normalized.append(' ');
436	            }
437	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
438	        }
439	        return normalized.toString();
440	    }
441	
442	    /**
443	     * Determines whether the given normalized E.164 telephone is already used by any owner other
444	     * than the one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g.
445	     * on create). Stored telephones are compared by their E.164 value so that differently formatted
446	     * inputs representing the same number are treated as duplicates.
447	     *
448	     * @param normalizedTelephone the already-normalized E.164 telephone to look for
449	     * @param excludeId           id of an owner to ignore during the check, or {@code null} for none
450	     * @return {@code true} if another owner already uses the telephone
451	     */
452	    private boolean isTelephoneInUse(String normalizedTelephone, Integer excludeId) {
453	        for (Owner existing : this.clinicService.findAllOwners()) {
454	            if (excludeId != null && excludeId.equals(existing.getId())) {
455	                continue;
456	            }
457	            if (normalizedTelephone.equals(toComparableTelephone(existing.getTelephone()))) {
458	                return true;
459	            }
460	        }
461	        return false;
462	    }
463	
464	}
